export const CutFontFaces=[{"family": "CutBarlow", "weight": "900", "style": "normal", "source": "data:font/woff2;base64,"}, {"family": "CutItalic", "weight": "900", "style": "italic", "source": "data:font/woff2;base64,"}, {"family": "CutTall", "weight": "400", "style": "normal", "source": "data:font/woff2;base64,"}, {"family": "CutOswald", "weight": "700", "style": "normal", "source": "data:font/woff2;base64,"}, {"family": "CutSaira", "weight": "800", "style": "normal", "source": "data:font/woff2;base64,"}, {"family": "CutBlock", "weight": "400", "style": "normal", "source": "data:font/woff2;base64,"}];
let cutFontReady;
export function loadCutFonts(){
 if(!cutFontReady)cutFontReady=Promise.all(CutFontFaces.map(item=>{
  const face=new FontFace(item.family,`url(${item.source})`,{weight:item.weight,style:item.style});
  return face.load().then(font=>document.fonts.add(font));
 }));return cutFontReady;
}
